begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
create function pg_temp.denied(stmt text) returns void language plpgsql as $$ begin begin execute stmt;exception when insufficient_privilege or raise_exception then return;end;raise exception 'Unexpectedly permitted: %',stmt;end $$;
insert into auth.users(id) values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
insert into public.books(id,owner_id,local_book_id,title,format) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','txt:original-hash','Book','txt');
insert into public.book_sources(id,book_id,owner_id,file_hash,extraction_version,source_object,manifest) values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','original-hash','pdf-text-v1','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb/source.txt',jsonb_build_object('sourceSha256',repeat('a',64)));
set local role service_role;
select public.eazo_submit_job('11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','test','model','pipeline') as job \gset
select pg_temp.assert(public.eazo_submit_job('11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','test','model','pipeline')=:'job','idempotent submission');
select pg_temp.denied($q$select public.eazo_submit_job('11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','test','different','pipeline')$q$);
select pg_temp.denied($q$select public.eazo_submit_job('11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','another','model','pipeline')$q$);
select pg_temp.assert(public.eazo_reserve_dispatch(:'job','11111111-1111-4111-8111-111111111111'),'first dispatch reserved');
select pg_temp.assert(not public.eazo_reserve_dispatch(:'job','11111111-1111-4111-8111-111111111111'),'duplicate dispatch rejected');
select pg_temp.assert(public.eazo_worker('claim',:'job','cccccccc-cccc-4ccc-8ccc-cccccccccccc')->>'book_id'='txt:original-hash','source identity preserved');
select pg_temp.assert(public.eazo_worker('claim',:'job','dddddddd-dddd-4ddd-8ddd-dddddddddddd')->>'busy'='true','duplicate claim busy');
select public.eazo_worker('write',:'job','cccccccc-cccc-4ccc-8ccc-cccccccccccc',jsonb_build_object('key','phase/a.json','hash',repeat('a',64),'object','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa/'||:'job'||'/checkpoints/'||repeat('a',64)||'.json'));
select pg_temp.assert(public.eazo_worker('list',:'job','cccccccc-cccc-4ccc-8ccc-cccccccccccc','{"prefix":"phase/"}')='["a.json"]','checkpoint listing');
update public.analysis_jobs set lease_expires_at=now()-interval '1 second' where id=:'job';
select public.eazo_worker('claim',:'job','dddddddd-dddd-4ddd-8ddd-dddddddddddd');
select pg_temp.assert(public.eazo_worker('read',:'job','dddddddd-dddd-4ddd-8ddd-dddddddddddd','{"key":"phase/a.json"}')->>'hash'=repeat('a',64),'checkpoint survives reclaim');
select pg_temp.denied(format('select public.eazo_worker(''heartbeat'',%L,''cccccccc-cccc-4ccc-8ccc-cccccccccccc'')',:'job'));
select public.eazo_worker('retry',:'job','dddddddd-dddd-4ddd-8ddd-dddddddddddd');
select public.eazo_worker('claim',:'job','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');
select public.eazo_worker('retry',:'job','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');
select pg_temp.assert((select status='failed' and attempt=3 from public.analysis_jobs where id=:'job'),'three-attempt ceiling');
select pg_temp.assert(public.eazo_worker('claim',:'job','ffffffff-ffff-4fff-8fff-ffffffffffff') is null,'terminal no-op');
select pg_temp.assert(bool_and(public.eazo_generation_quota('11111111-1111-4111-8111-111111111111')),'50 permitted') from generate_series(1,50);
select pg_temp.assert(not public.eazo_generation_quota('11111111-1111-4111-8111-111111111111'),'51st rejected');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.denied('select * from public.analysis_checkpoints');
select pg_temp.denied('select * from public.generation_usage');
select pg_temp.denied(format('select public.eazo_worker(''claim'',%L,gen_random_uuid())',:'job'));
rollback;
